                 String externalIds = action.getExternalChildIDs();
-                String []jobIds = externalIds.split(",");
+                if (externalIds != null && !externalIds.trim().isEmpty()) {
+                    String []jobIds = externalIds.split(",");

-                for(String jobId : jobIds) {
